from collections import Counter

def rearange_string(s):
    count = Counter(s)
    max_count = max(count.values())
    if max_count > (len(s) + 1) // 2:
        return None

    max_char = max(count, key=count.get)
    result = [max_char]
    count[max_char] -= 1

    for char in sorted(count, key=count.get, reverse=True):
        while count[char] > 0:
            if result[-1] == char:
                result.insert(0, char)
            else:
                result.append(char)
            count[char] -= 1

    return ''.join(result)

