def is_valid_parenthese(s):
    stack = []
    for char in s:
        if char in ['(', '[', '{']:
            stack.append(char)
        elif char == ')' and stack and stack[-1] == '(':
            stack.pop()
        elif char == ']' and stack and stack[-1] == '[':
            stack.pop()
        elif char == '}' and stack and stack[-1] == '{':
            stack.pop()
        else:
            return False
    return not stack

